"""Render the actual companion HTML with clearly labelled fixture content."""
from pathlib import Path
from playwright.sync_api import sync_playwright
from PIL import Image
import json,re
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'artifacts/showcase-1.2.1';MEDIA=OUT/'media'
markup=(ROOT/'src/Launcher.Companion/Companion.html').read_text(encoding='utf-8-sig')
fixture=dict(Pin='12345678',Fingerprint='A1B2C3D4'*8,Addresses=['https://192.168.1.10:17842'],Connected=True,Snapshot=dict(Notes=[dict(Id='sample',Title='Weekend',Text='Walk the ridge early.\nBook a table for Saturday.\nFinish the shelf in the study.',UpdatedAt=0),dict(Id='sample2',Title='Shopping',Text='Coffee beans, tomatoes, sourdough.',UpdatedAt=0)],FolderShared=True,AllowUploads=False,Device='Android'))
start=markup.index('async function api(');end=markup.index('async function update()',start)
markup=markup[:start]+'async function api(path,body){return '+json.dumps(fixture)+'}\n'+markup[end:]
markup=markup.replace('update();setInterval(update,4000);',"update().then(()=>{edit(state.Snapshot.Notes[0]);document.querySelector('#pair').style.display='none';document.querySelector('#message').textContent='INTERFACE ILLUSTRATION · SAMPLE CONTENT · NOT A LIVE CONNECTION';});")
markup=markup.replace('<section><h2>Photos & files</h2>','<section><h2>Photos & files</h2>')
markup=markup.replace('<div id="files" class="files"></div>','<div id="files" class="files"><div class="file"><p>Weekend photos</p><small>Folder</small><br><button>Open folder</button></div><div class="file"><p>Travel notes.pdf</p><small>PDF document · 185 KB</small><br><button>Download</button></div><div class="file"><p>Workshop sketch.png</p><small>Image · 720 KB</small><br><button>Preview photo</button><button>Download</button></div></div>')
file=OUT/'companion-desktop-illustration.html';file.write_text(markup,encoding='utf-8')
with sync_playwright() as p:
 browser=p.chromium.launch(headless=True,channel='chrome');page=browser.new_page(viewport={'width':1440,'height':1100});page.goto(file.as_uri());page.screenshot(path=str(OUT/'companion-desktop-illustration.png'),full_page=True)
 # Frame this preview as a desktop mockup, retaining its disclosure line.
 css='body{margin:0;background:#10140d;color:#f4f5ef;font-family:Arial}main{width:1920px;height:1080px;position:relative;background:radial-gradient(ellipse at 90% 0%,#364126,transparent 65%),#10140d}h1{font-size:62px;letter-spacing:-2px;margin:0}p{font-size:23px;color:#a7b096;line-height:1.5}.copy{position:absolute;left:90px;top:95px}.eyebrow{font-size:20px;color:#e4ff00;letter-spacing:3px;margin-bottom:20px}.browser{position:absolute;left:750px;top:75px;width:1070px;height:890px;border:1px solid #58614b;border-radius:20px;overflow:hidden;box-shadow:0 30px 70px #000a;background:#090b07}.bar{height:36px;background:#242a1c;color:#b0b99f;font-size:12px;line-height:36px;padding-left:20px}.browser img{width:100%;height:850px;object-fit:contain;object-position:top}.foot{position:absolute;left:90px;bottom:55px;font-size:17px;color:#88937c;line-height:1.7}'
 cover=OUT/'desktop-mockup.html';cover.write_text('<style>'+css+'</style><main><div class="copy"><div class="eyebrow">LAUNCHER COMPANION</div><h1>A little more room<br>to finish a thought.</h1><p>Edit a note at your desk.<br>Browse your chosen folder.<br>Keep it on your own network.</p><p style="font-size:17px;margin-top:60px">Windows x64 · Self-contained EXE<br>Code and fingerprint pairing<br>Optional uploads · 16 MB per file</p></div><div class="browser"><div class="bar">● ● ●　　　　 Launcher Companion · Local desktop page</div><img src="'+(OUT/'companion-desktop-illustration.png').as_uri()+'"></div><div class="foot">INTERFACE ILLUSTRATION · SAMPLE CONTENT<br>NOT A LIVE DEVICE CAPTURE</div></main>',encoding='utf-8');page.set_viewport_size({'width':1920,'height':1080});page.goto(cover.as_uri());page.screenshot(path=str(OUT/'desktop-mockup.png'));browser.close()
target=MEDIA/'launcher-121-desktop.webp';Image.open(OUT/'desktop-mockup.png').convert('RGB').save(target,'WEBP',quality=93,method=6)
gallery=json.loads((OUT/'gallery.json').read_text(encoding='utf-8'));gallery=[g for g in gallery if g['src']!='/media/'+target.name];gallery.append(dict(src='/media/'+target.name,caption='Windows companion',alt='Launcher Companion notes and shared files in a desktop browser',note='Companion HTML rendered with sample data as an interface illustration. Not a live connected-session screenshot.',width=1920,height=1080,heroEnabled=False));(OUT/'gallery.json').write_text(json.dumps(gallery,ensure_ascii=False,indent=2),encoding='utf-8')
print('Rendered the Windows companion mockup.')
